#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/* A single-producer, single-consumer byte ring buffer.
 * The capacity must be a power of two so that indices can be wrapped with a
 * mask. head and tail grow without bound; their difference is the number of
 * stored bytes, which unsigned arithmetic keeps correct across overflow. */
typedef struct {
    uint8_t *data;
    size_t capacity;   /* power of two */
    size_t head;       /* next byte to write */
    size_t tail;       /* next byte to read */
} ring_t;

static bool is_power_of_two(size_t x) {
    return x != 0 && (x & (x - 1)) == 0;
}

bool ring_init(ring_t *r, uint8_t *storage, size_t capacity) {
    if (r == NULL || storage == NULL || !is_power_of_two(capacity)) {
        return false;
    }
    r->data = storage;
    r->capacity = capacity;
    r->head = 0;
    r->tail = 0;
    return true;
}

size_t ring_used(const ring_t *r) {
    return r->head - r->tail;
}

size_t ring_free(const ring_t *r) {
    return r->capacity - ring_used(r);
}

/* Copies up to len bytes in at most two memcpy calls; returns bytes written. */
size_t ring_write(ring_t *r, const uint8_t *src, size_t len) {
    size_t n = len < ring_free(r) ? len : ring_free(r);
    size_t mask = r->capacity - 1;
    size_t start = r->head & mask;
    size_t first = n < r->capacity - start ? n : r->capacity - start;
    memcpy(r->data + start, src, first);
    memcpy(r->data, src + first, n - first);
    r->head += n;
    return n;
}

size_t ring_read(ring_t *r, uint8_t *dst, size_t len) {
    size_t n = len < ring_used(r) ? len : ring_used(r);
    size_t mask = r->capacity - 1;
    size_t start = r->tail & mask;
    size_t first = n < r->capacity - start ? n : r->capacity - start;
    memcpy(dst, r->data + start, first);
    memcpy(dst + first, r->data, n - first);
    r->tail += n;
    return n;
}

/* Returns the byte at offset i from the read position without consuming it. */
int ring_peek(const ring_t *r, size_t i) {
    if (i >= ring_used(r)) {
        return -1;
    }
    return r->data[(r->tail + i) & (r->capacity - 1)];
}

// Utilities for rate-limiting event handlers in the browser.

/**
 * Returns a function that delays calling `fn` until `wait` milliseconds have
 * passed without another call. The returned function exposes `cancel` and
 * `flush` so callers can discard or force the pending invocation.
 */
export function debounce(fn, wait, { leading = false } = {}) {
  let timer = null;
  let lastArgs = null;
  let lastThis = null;

  function invoke() {
    const args = lastArgs;
    const self = lastThis;
    lastArgs = lastThis = null;
    return fn.apply(self, args);
  }

  function debounced(...args) {
    const callNow = leading && timer === null;
    lastArgs = args;
    lastThis = this;
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!leading && lastArgs !== null) {
        invoke();
      }
    }, wait);
    if (callNow) {
      return invoke();
    }
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
    lastArgs = lastThis = null;
  };

  debounced.flush = () => {
    if (timer !== null && lastArgs !== null) {
      clearTimeout(timer);
      timer = null;
      return invoke();
    }
  };

  return debounced;
}

/**
 * Calls `fn` at most once every `interval` milliseconds, always delivering
 * the most recent arguments when the interval ends.
 */
export function throttle(fn, interval) {
  let last = 0;
  let pending = null;

  return function throttled(...args) {
    const now = Date.now();
    const remaining = interval - (now - last);
    if (remaining <= 0) {
      last = now;
      fn.apply(this, args);
    } else if (pending === null) {
      pending = setTimeout(() => {
        pending = null;
        last = Date.now();
        fn.apply(this, args);
      }, remaining);
    }
  };
}

// Example: resize the chart at most every 100 ms and save the draft once typing stops.
const onResize = throttle(() => chart.resize(window.innerWidth), 100);
const saveDraft = debounce((text) => storage.setItem("draft", text), 500);
window.addEventListener("resize", onResize);
editor.addEventListener("input", (event) => saveDraft(event.target.value));

-- Monthly revenue per region, with each month's share of the regional total
-- and the change from the previous month.
WITH monthly AS (
    SELECT
        r.name AS region,
        date_trunc('month', o.placed_at) AS month,
        SUM(oi.quantity * oi.unit_price) AS revenue
    FROM orders o
    JOIN order_items oi ON oi.order_id = o.id
    JOIN customers c ON c.id = o.customer_id
    JOIN regions r ON r.id = c.region_id
    WHERE o.status = 'completed'
      AND o.placed_at >= DATE '2024-01-01'
    GROUP BY r.name, date_trunc('month', o.placed_at)
)
SELECT
    region,
    month,
    revenue,
    ROUND(100.0 * revenue / SUM(revenue) OVER (PARTITION BY region), 2) AS pct_of_region,
    revenue - LAG(revenue) OVER (PARTITION BY region ORDER BY month) AS change
FROM monthly
ORDER BY region, month;

// The same aggregation in Rust over records that are already loaded.
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub struct Sale {
    pub region: String,
    pub month: u32,
    pub amount_cents: i64,
}

pub fn monthly_totals(sales: &[Sale]) -> BTreeMap<(String, u32), i64> {
    let mut totals = BTreeMap::new();
    for sale in sales {
        *totals
            .entry((sale.region.clone(), sale.month))
            .or_insert(0) += sale.amount_cents;
    }
    totals
}

pub fn month_over_month(totals: &BTreeMap<(String, u32), i64>) -> Vec<(String, u32, Option<i64>)> {
    let mut out = Vec::with_capacity(totals.len());
    let mut previous: Option<(&str, i64)> = None;
    for ((region, month), total) in totals {
        let change = match previous {
            Some((prev_region, prev_total)) if prev_region == region => Some(total - prev_total),
            _ => None,
        };
        out.push((region.clone(), *month, change));
        previous = Some((region.as_str(), *total));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn change_resets_between_regions() {
        let sales = vec![
            Sale { region: "east".into(), month: 1, amount_cents: 500 },
            Sale { region: "east".into(), month: 2, amount_cents: 800 },
            Sale { region: "west".into(), month: 1, amount_cents: 300 },
        ];
        let rows = month_over_month(&monthly_totals(&sales));
        assert_eq!(rows[1].2, Some(300));
        assert_eq!(rows[2].2, None);
    }
}
